const items = $input.all();

if (!items.length || !items[0].json.StudentName) {
  return [{ json: { hasData: false } }];
}

// Group fee records by student
const students = {};
items.forEach(item => {
  const name = item.json.StudentName;
  if (!name) return;
  if (!students[name]) {
    students[name] = {
      studentName: name,
      studentId:   item.json.StudentID,
      records:     []
    };
  }
  students[name].records.push({
    month:       item.json.Month,
    amountDue:   parseFloat(item.json.AmountDue)  || 0,
    amountPaid:  parseFloat(item.json.AmountPaid) || 0,
    status:      item.json.Status || 'Pending',
    dueDate:     item.json.DueDate,
    paidDate:    item.json.PaidDate || null
  });
});

// Calculate risk score per student
const results = [];
Object.values(students).forEach(student => {
  const records    = student.records;
  const total      = records.length;
  const paid       = records.filter(r => r.status === 'Paid').length;
  const partial    = records.filter(r => r.status === 'Partial').length;
  const pending    = records.filter(r => r.status === 'Pending').length;
  const missing    = records.filter(r => r.status === 'Missing').length;

  // Calculate payment rate
  const paymentRate = total > 0 ? Math.round((paid / total) * 100) : 100;

  // Check if current month is already paid
  const now = new Date();
  const months = ['January','February','March','April','May','June',
                  'July','August','September','October','November','December'];
  const currentMonth = months[now.getMonth()] + ' ' + now.getFullYear();
  const currentRecord = records.find(r => r.month === currentMonth);
  const alreadyPaid = currentRecord && currentRecord.status === 'Paid';

  if (alreadyPaid) return;

  // Calculate risk score (0-100, higher = more risk)
  let riskScore = 0;
  if (paymentRate < 50)  riskScore += 40;
  else if (paymentRate < 75) riskScore += 25;
  else if (paymentRate < 90) riskScore += 10;

  if (pending > 1)  riskScore += 20;
  if (missing > 0)  riskScore += 25;
  if (partial > 1)  riskScore += 15;

  // Check last 3 months pattern
  const recent = records.slice(-3);
  const recentUnpaid = recent.filter(r => r.status !== 'Paid').length;
  if (recentUnpaid >= 2) riskScore += 20;
  if (recentUnpaid === 3) riskScore += 15;

  riskScore = Math.min(riskScore, 100);

  const riskLevel = riskScore >= 70 ? 'High' :
                    riskScore >= 40 ? 'Medium' : 'Low';

  results.push({
    hasData:        true,
    studentName:    student.studentName,
    studentId:      student.studentId,
    totalMonths:    total,
    paidMonths:     paid,
    partialMonths:  partial,
    pendingMonths:  pending,
    missingMonths:  missing,
    paymentRate:    paymentRate,
    riskScore:      riskScore,
    riskLevel:      riskLevel,
    currentMonth:   currentMonth,
    currentStatus:  currentRecord ? currentRecord.status : 'No record',
    recentPattern:  recent.map(r => r.status).join(' → '),
    recordsSummary: JSON.stringify(records.slice(-6))
  });
});

if (!results.length) {
  return [{ json: { hasData: false, message: 'All students have paid this month.' } }];
}

// Sort by risk score descending
results.sort((a, b) => b.riskScore - a.riskScore);

return results.map(r => ({ json: r }));

const student = $('Loop Over Items').item.json;
const records = JSON.parse(student.recordsSummary);

const historyText = records.map(r =>
  `${r.month}: ${r.status} (Due: PKR ${r.amountDue}, Paid: PKR ${r.amountPaid})`
).join('\n');

const prompt = `You are a financial analyst for a tuition center. Based on this student's payment history, write ONE sentence predicting whether they will pay this month's fee on time and why.

Student: ${student.studentName}
Payment rate: ${student.paymentRate}%
Recent pattern: ${student.recentPattern}
Risk score: ${student.riskScore}/100
Risk level: ${student.riskLevel}

Last 6 months history:
${historyText}

Write exactly ONE sentence. Be direct and specific. No greetings.`;

return [{
  json: {
    studentName:   student.studentName,
    riskScore:     student.riskScore,
    riskLevel:     student.riskLevel,
    paymentRate:   student.paymentRate,
    recentPattern: student.recentPattern,
    currentStatus: student.currentStatus,
    currentMonth:  student.currentMonth,
    pendingMonths: student.pendingMonths,
    missingMonths: student.missingMonths,
    ollamaBody: JSON.stringify({
      model:  'llama3.2:1b',
      prompt: prompt,
      stream: false
    })
  }
}];

const ollamaData  = $input.all()[0].json;
const studentData = $('Build Default Prompt').item.json;
const aiPrediction = (ollamaData.response || 'Prediction unavailable.').trim();

const riskEmoji = studentData.riskLevel === 'High'   ? '🔴' :
                  studentData.riskLevel === 'Medium'  ? '🟡' : '🟢';

const message = [
  `${riskEmoji} ${studentData.studentName} — Risk: ${studentData.riskLevel} (${studentData.riskScore}/100)`,
  `📊 Payment rate: ${studentData.paymentRate}% | Pattern: ${studentData.recentPattern}`,
  `📅 This month (${studentData.currentMonth}): ${studentData.currentStatus}`,
  `🤖 ${aiPrediction}`,
  studentData.riskLevel === 'High'
    ? `⚡ Action needed: Contact parent immediately.`
    : studentData.riskLevel === 'Medium'
    ? `👀 Monitor closely and send reminder.`
    : `✅ Low risk — standard reminder sufficient.`,
  '─────────────────────'
].join('\n');

return [{ json: { message, riskLevel: studentData.riskLevel } }];
